import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百一十七章 蜂蜜会与蜂蜜聚集到一起","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/117第一百一十七章 蜂蜜会与蜂蜜聚集到一起.md","filePath":"meditation/巴利文大藏经/117第一百一十七章 蜂蜜会与蜂蜜聚集到一起.md"}'),o={name:"meditation/巴利文大藏经/117第一百一十七章 蜂蜜会与蜂蜜聚集到一起.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百一十七章-蜂蜜会与蜂蜜聚集到一起" tabindex="-1">第一百一十七章 蜂蜜会与蜂蜜聚集到一起 <a class="header-anchor" href="#第一百一十七章-蜂蜜会与蜂蜜聚集到一起" aria-label="Permalink to &quot;第一百一十七章 蜂蜜会与蜂蜜聚集到一起&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应16经/有偈经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间的众生如同界（界解释，见第一百零三章）一样，相同特性的事物会聚集、合流到一起，也就是凶恶歹毒的人会与卑劣恶毒的念想聚集、合流到一起，恶人会与恶人聚集、合流到一起。</p><p>弟子们，过去世、现在世、未来世的众生也如同界一样，相同特性的事物会聚集、合流到一起，也就是过去世、现在世、未来世凶恶歹毒的众生会与卑劣恶毒的念想聚集、合流到一起，过去世、现在世、未来世恶毒的众生会与恶毒的众生聚集、合流到一起。</p><p>弟子们，就如同屎粪与屎粪聚集、合流到一起；尿与尿聚集、合流到一起；口痰与口痰聚集、合流到一起；浓血与浓血聚集、合流到一起；污血与污血聚集、合流到一起。弟子们，同样的道理，过去世、现在世、未来世的众生也如同界一样，相同特性的事物会聚集、合流到一起，也就是过去世、现在世、未来世凶恶歹毒的众生会与卑劣恶毒的念想聚集、合流到一起，过去世、现在世、未来世恶毒的众生会与恶毒的众生聚集、合流到一起。</p><p>弟子们，世间的众生如同界一样，相同特性的事物会聚集、合流到一起，也就是善良温和的人会与高尚仁慈的念想聚集、合流到一起，善人会与善人聚集、合流到一起。</p><p>弟子们，过去世、现在世、未来世的众生也如同界一样，相同特性的事物会聚集、合流到一起，也就是过去世、现在世、未来世善良温和的众生会与高尚仁慈的念想聚集、合流到一起，过去世、现在世、未来世善良的众生会与善良的众生聚集、合流到一起。</p><p>弟子们，就如同乳汁与乳汁聚集、合流到一起；油与油聚集、合流到一起；奶酥与奶酥聚集、合流到一起；蜂蜜与蜂蜜聚集、合流到一起；糖浆与糖浆聚集、合流到一起。弟子们，同样的道理，过去世、现在世、未来世的众生也如同界一样，相同特性的事物会聚集、合流到一起，也就是过去世、现在世、未来世善良温和的众生会与高尚仁慈的念想聚集、合流到一起，过去世、现在世、未来世善良的众生会与善良的众生聚集、合流到一起。</p><p>弟子们，眼睛、耳朵、鼻子、舌头、身体、内心接触到物质事物、声音、气味、味道、触觉、念想的时候就会生起欲望，当欲望生起的时候，就会在欲望的森林中迷失。不接触外界的事物，欲望就被切断了，欲望就无法生起。</p><p>如同在汹涌澎湃的大海上行驶的小舟，随时都可能被海浪吞噬沉没一样。松懈、懒惰的修行人随时都可能被欲望的大海吞噬沉没，从而丧失掉之前清净的境界。因此要远离那些松懈、懒惰的修行人。要亲近精进修行的圣者，并且要以这些圣者为榜样，让自己的内心不被外界的事物所迷惑，让自己的内心不再胡思乱想，不再散乱，让自己的内心保持清净的境界，让自己的内心不生起任何的念想，这样就不会迷失在欲望的森林之中，这样就不会被烦恼和痛苦束缚和捆绑。这样经常与圣者在一起修行，经常保持内心的清净境界，不让内心生起任何的念想，那么就能除灭一切的烦恼和痛苦，就能从生死轮回中永远的解脱出来，就能最终达到不生不灭涅槃的境界。”</p><p>这时，佛陀说偈言：</p><p>「欲情之下生，由触而发生，</p><p>若无触则断。如于大海上，</p><p>乘小舟必没，如是入懈怠，</p><p>净命亦沉没。然彼懈怠者，</p><p>离无精进者，亲近贤圣者，</p><p>俱与贤圣住，常于勤精进，</p><p>专注禅思者，终达涅槃境。」</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',20)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
